function currentAddedContract(pathValue: string, focus: string): TestContractAuditEntry {
  return entry(
    pathValue,
    `the base checkpoint had no dedicated executable contract for ${focus}`,
    `the added contract proves ${focus} with exact positive and fail-closed assertions`,
    `make ${focus} independently reviewable on the current canonical candidate`,
    "the file is additive; it removes no base test or RED case and changes no existing denominator, timeout, retry, matcher, fixture or provider boundary",
  );
}

function currentAlignedContract(pathValue: string, focus: string): TestContractAuditEntry {
  return entry(
    pathValue,
    `${focus} was asserted against a predecessor owner, synchronous fixture or stale projection`,
    `${focus} is asserted against the current canonical owner while preserving its positive and fail-closed boundary`,
    `align ${focus} with the single backend, immutable revision and durable artifact lifecycle`,
    "the reviewed diff preserves the scenario or strengthens exact ownership; no test is focused, skipped or deleted and no denominator, timeout, retry, matcher or failure condition is relaxed",
  );
}

